// STATIC_EXPORT=1 (the build service) writes a static site to ./out; the dev server keeps its own .next.
const exporting = process.env.STATIC_EXPORT === '1'

export default {
  ...(exporting ? { output: 'export' } : {}),
  distDir: exporting ? '.next-build' : '.next',
  poweredByHeader: false,
  allowedDevOrigins: [process.env.APP_DOMAIN].filter(Boolean),
  // Upload URLs are served by nginx already (WebP variants are generated by the API), so Next does not re-encode them.
  images: { unoptimized: true },
  // Classic caching: `fetch(..., { next: { revalidate, tags } })` plus on-demand revalidateTag. No Cache Components.
}
